import { at, found, json, lang, listed, of, sentence, truth, under } from '@lapxo/topos/capsule';
import type { Asked } from '@lapxo/topos/capsule';

const versioned = (text: string | undefined): Record<string, string> => Object.fromEntries((text ?? '').split('|').filter(Boolean)
  .map((one) => [one.slice(0, one.lastIndexOf('@')), one.slice(one.lastIndexOf('@') + 1)]));

/**
 * The manifest of the tree's copy: what the place holds, read by the tree's own resolver through typesVersions, main and
 * types, and by a resolver asking for sources through the source each subpath was built from. Nothing is a default: a
 * field absent from the place's lines is absent here, and the description is its prose written as its language writes.
 */
export const manifest = (asked: Asked): readonly string[] => {
  const [subpaths, source, what] = [under(asked, 'exports'), at(asked, 'source'), found(asked, `prose/${lang(asked)}/what`)];
  const resolved = (built: string): Record<string, string> => ({ ...(source ? { source: `./${source}${built.slice(built.indexOf('/'))}.ts` } : {}), types: `./${built}.d.ts`, default: `./${built}.js` });
  const root = subpaths.find(([sub]) => sub === '')?.[1] ?? '';
  const [repository, kind, side] = [at(asked, 'repository'), at(asked, 'type'), at(asked, 'sideEffects')];
  return json({
    name: at(asked, 'name'), version: at(asked, 'version'), description: what === undefined ? undefined : sentence(asked, of(what, 'about')),
    ...(kind ? { type: kind } : {}), license: at(asked, 'license'), author: at(asked, 'author'),
    ...(repository ? { repository: { type: 'git', url: `git+${repository}.git` } } : {}), keywords: (at(asked, 'keywords') ?? '').split('|').filter(Boolean),
    ...(side === undefined ? {} : { sideEffects: truth(side) }), engines: { node: at(asked, 'engines') },
    typesVersions: { '*': Object.fromEntries(subpaths.filter(([sub]) => sub !== '').map(([sub, built]) => [sub, [`${built}.d.ts`]])) },
    exports: { ...Object.fromEntries(subpaths.map(([sub, built]) => [sub === '' ? '.' : `./${sub}`, resolved(built)])), [`./${asked.shape}`]: `./${asked.shape}` },
    files: listed(asked, 'audit/wire/ships'), scripts: Object.fromEntries(under(asked, 'scripts').filter(([name]) => name !== '')),
    ...(at(asked, 'dependencies') === undefined ? {} : { dependencies: versioned(at(asked, 'dependencies')) }), devDependencies: versioned(at(asked, 'devDependencies')),
    main: `${root}.js`, types: `${root}.d.ts`,
  });
};

import type { Asked, Handed } from '@lapxo/topos/capsule';

const of = (line: Handed, field: string): string => line[field] ?? '';
const typed = (value: string): string | boolean => (value === 'true' ? true : value === 'false' ? false : value);
const listed = (input: Asked, scope: string): readonly string[] => of(input.lines.find((one) => of(one, 'scope') === scope) ?? {}, 'value').split('|').filter(Boolean);
const shapeOf = (input: Asked, region: string): string => of(input.lines.find((one) => of(one, 'scope').startsWith('view/') && of(one, 'value').split('|').some((token) => token.split('@')[0] === region)) ?? {}, 'shape');
const said = (input: Asked, shape: string, field: string): string | undefined => ((line) => (line === undefined ? undefined : of(line, 'value')))(input.lines.find((one) => of(one, 'scope') === field && of(one, 'shape') === shape));
const under = (input: Asked, shape: string, head: string): readonly (readonly [string, string])[] => input.lines
  .filter((one) => of(one, 'shape') === shape && (of(one, 'scope') === head || of(one, 'scope').startsWith(`${head}/`)))
  .map((one) => [of(one, 'scope').slice(head.length + (of(one, 'scope') === head ? 0 : 1)), of(one, 'value')] as const)
  .sort((a, b) => (a[0] === '' ? -1 : b[0] === '' ? 1 : a[0].localeCompare(b[0])));
const json = (value: unknown): readonly string[] => `${JSON.stringify(value, null, 2)}\n`.split('\n').slice(0, -1);
const versioned = (value: string | undefined): Record<string, string> => Object.fromEntries((value ?? '').split('|').filter(Boolean).map((one) => [one.slice(0, one.lastIndexOf('@')), one.slice(one.lastIndexOf('@') + 1)]));

function sentence(input: Asked, text: string): string {
  const lang = listed(input, 'lang')[0] ?? '';
  const rule = listed(input, `form/prose/${lang}/sentence`);
  let end = text.length;
  while (end > 0 && '. \n'.includes(text.charAt(end - 1))) end -= 1;
  const start = rule.includes('capital') ? `${text.charAt(0).toUpperCase()}${text.slice(1, end)}` : text.slice(0, end);
  return rule.includes('period') ? `${start}.` : start;
}

function build(input: Asked): readonly string[] {
  const shape = shapeOf(input, 'build');
  if (!shape) return [];
  const options = under(input, shape, 'build').filter(([name]) => name !== '');
  const include = options.find(([name]) => name === 'include')?.[1];
  return json({ compilerOptions: Object.fromEntries(options.filter(([name]) => name !== 'include').map(([name, value]) => [name, typed(value)])), ...(include === undefined ? {} : { include: include.split('|') }) });
}

function manifest(input: Asked, published: boolean): readonly string[] {
  const shape = shapeOf(input, published ? 'published-manifest' : 'manifest');
  if (!shape) return [];
  const lang = listed(input, 'lang')[0];
  const what = lang === undefined ? undefined : input.lines.find((one) => of(one, 'scope') === `prose/${lang}/what`);
  const subpaths = under(input, shape, 'exports');
  const source = published ? undefined : said(input, shape, 'source');
  const resolved = (built: string): Record<string, string> => ({ ...(source ? { source: `./${source}${built.slice(built.indexOf('/'))}.ts` } : {}), types: `./${built}.d.ts`, default: `./${built}.js` });
  const exports: Record<string, unknown> = Object.fromEntries(subpaths.map(([sub, built]) => [sub === '' ? '.' : `./${sub}`, resolved(built)]));
  exports[`./${shape}`] = `./${shape}`;
  const root = subpaths.find(([sub]) => sub === '')?.[1] ?? '';
  const [repository, kind, side] = [said(input, shape, 'repository'), said(input, shape, 'type'), said(input, shape, 'sideEffects')];
  return json({
    name: said(input, shape, 'name'), version: said(input, shape, 'version'), description: what === undefined ? undefined : sentence(input, of(what, 'about')),
    ...(kind ? { type: kind } : {}), license: said(input, shape, 'license'), author: said(input, shape, 'author'),
    ...(repository ? { repository: { type: 'git', url: `git+${repository}.git` } } : {}), keywords: (said(input, shape, 'keywords') ?? '').split('|').filter(Boolean),
    ...(side === undefined ? {} : { sideEffects: typed(side) }), engines: { node: said(input, shape, 'engines') },
    ...(published ? {} : { typesVersions: { '*': Object.fromEntries(subpaths.filter(([sub]) => sub !== '').map(([sub, built]) => [sub, [`${built}.d.ts`]])) } }),
    exports, files: listed(input, 'audit/wire/ships'), scripts: Object.fromEntries(under(input, shape, 'scripts').filter(([name]) => name !== '')),
    ...(said(input, shape, 'dependencies') === undefined ? {} : { dependencies: versioned(said(input, shape, 'dependencies')) }), devDependencies: versioned(said(input, shape, 'devDependencies')),
    ...(published ? {} : { main: `${root}.js`, types: `${root}.d.ts` }),
  });
}

/**
 * A manifest is a render of the lock, in the two copies one lock makes: the tree's, which the tree's own resolver
 * still reads through `typesVersions`, `main` and `types`, and the place's, which a consumer reads through `exports`
 * alone, a type and a default for each subpath, and the tree's copy the source it was built from when the lock names
 * where the sources lie. Nothing here is a default — a field absent from the lock is absent
 * from the manifest, the description is the place's own prose in the language its lock names, written as that
 * language writes a sentence, or nothing, and how the place builds is every option one line, its sources one list.
 */
export function render(input: Asked): readonly string[] {
  return input.region === 'build' ? build(input) : manifest(input, input.region === 'published-manifest');
}

import { foldRegion } from './field/field.ts';
import type { Fold, Point, Region } from './field/field.ts';

/**
 * Replay is the proof: what landed is folded again over its region, and the same points give the same verdicts in any
 * order and on any machine. It is the one loop of the field with a verdict as its local reading; nothing is run again.
 */
export function replay<T>(landed: readonly Point[], where: Region, verdict: (met: readonly Point[]) => T): readonly Fold<T>[] {
  return foldRegion(landed, where, verdict);
}
